import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String n = br.readLine();int luckyCount = 0;for (int i = 0; i < n.length(); i++) {char c = n.charAt(i);if (c == '4' || c == '7') {luckyCount++;}}if (isLucky(luckyCount)) {System.out.println("YES");} else {System.out.println("NO");}}private static boolean isLucky(int n) {if (n == 0) return false;String s = String.valueOf(n);for (int i = 0; i < s.length(); i++) {if (s.charAt(i) != '4' && s.charAt(i) != '7') {return false;}}return true;}}